using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using NAudio.CoreAudioApi;
using NAudio.Wave;
class RecordingSettings {
 public bool FullScreen=false,SystemAudio=true,Microphone=true;public string Directory=@"D:\ScreenText\Recordings";
 public RecordingSettings Copy(){return (RecordingSettings)MemberwiseClone();}
}
static class RecordingRuntime {
 public static string ToolsDirectory=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"runtime");
 public static string Tool(string name){string path=Path.Combine(ToolsDirectory,name+".exe");if(!File.Exists(path))throw new Exception("录屏组件缺失："+name+".exe");return path;}
 public static string Q(string value){if(value.IndexOf('"')>=0||value.IndexOf('\r')>=0||value.IndexOf('\n')>=0)throw new Exception("路径包含不支持的字符");return "\""+value.TrimEnd('\\')+"\"";}
 public static string Run(string tool,string arguments,int timeout=180000){using(var process=new Process{StartInfo=new ProcessStartInfo(Tool(tool),arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}}){process.Start();var output=process.StandardOutput.ReadToEndAsync();var errors=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(timeout)){try{process.Kill();}catch{}throw new TimeoutException("视频处理超时，临时文件已保留");}Task.WaitAll(output,errors);if(process.ExitCode!=0)throw new Exception("视频处理失败："+errors.Result.Substring(Math.Max(0,errors.Result.Length-700)));return output.Result;}}
 public static void ValidateDirectory(string directory){var path=ShotStore.DirectoryPath(directory);System.IO.Directory.CreateDirectory(path);string probe=Path.Combine(path,".write-test-"+Guid.NewGuid().ToString("N"));using(File.Create(probe)){}File.Delete(probe);}
}
sealed class RecordingAudio:IDisposable {
 WasapiCapture capture;WasapiOut silentOutput;WaveFileWriter writer;MMDevice device;ManualResetEvent stopped=new ManualResetEvent(false);object gate=new object();bool started;public string Path;public int OffsetMs;public Exception Fault;
 public RecordingAudio(string path,bool system){Path=path;try{using(var devices=new MMDeviceEnumerator())device=devices.GetDefaultAudioEndpoint(system?DataFlow.Render:DataFlow.Capture,Role.Multimedia);capture=system?(WasapiCapture)new WasapiLoopbackCapture(device):new WasapiCapture(device);writer=new WaveFileWriter(path,capture.WaveFormat);if(system){silentOutput=new WasapiOut(device,AudioClientShareMode.Shared,false,100);silentOutput.Init(new SilenceProvider(capture.WaveFormat));}capture.DataAvailable+=(s,e)=>{try{lock(gate){if(writer!=null)writer.Write(e.Buffer,0,e.BytesRecorded);}}catch(Exception failure){Fault=failure;}};capture.RecordingStopped+=(s,e)=>{if(e.Exception!=null)Fault=e.Exception;stopped.Set();};}catch{Dispose();throw;}}
 public void Start(Stopwatch clock){OffsetMs=(int)clock.ElapsedMilliseconds;started=true;capture.StartRecording();if(silentOutput!=null)silentOutput.Play();}
 public void Dispose(){if(capture!=null){try{if(started){capture.StopRecording();stopped.WaitOne(4000);}}finally{capture.Dispose();capture=null;}}if(silentOutput!=null){silentOutput.Stop();silentOutput.Dispose();silentOutput=null;}lock(gate){if(writer!=null){if(writer.Length==0){int count=writer.WaveFormat.AverageBytesPerSecond/10;writer.Write(new byte[count],0,count);}writer.Dispose();writer=null;}}if(device!=null){device.Dispose();device=null;}stopped.Dispose();}
}
sealed class RecordingEngine:IDisposable {
 sealed class Segment {public string Video,Mixed;public List<string> Audio=new List<string>();public List<int> Delays=new List<int>();}
 RecordingSettings settings;Rectangle area;string work;List<Segment> segments=new List<Segment>();Segment current;Process encoder;List<RecordingAudio> audio=new List<RecordingAudio>();StringBuilder errorLog=new StringBuilder();ManualResetEvent ready;Stopwatch activeClock=new Stopwatch(),firstFrameClock=new Stopwatch();TimeSpan past;bool synthetic,disposed;public string OutputPath{get;private set;}public string RecoveryDirectory{get{return work;}}public bool Paused{get;private set;}public bool Finalized{get;private set;}public TimeSpan Duration{get{return past+activeClock.Elapsed;}}
 public RecordingEngine(RecordingSettings config,Rectangle region,bool syntheticVideo=false){settings=config.Copy();area=region;synthetic=syntheticVideo;RecordingRuntime.ValidateDirectory(settings.Directory);if(area.Width<16||area.Height<16)throw new Exception("录屏区域至少需要 16 × 16 像素");RecordingRuntime.Tool("ffmpeg");work=Path.Combine(settings.Directory,".recording-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);OutputPath=Path.Combine(settings.Directory,"recording-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6)+".mp4");}
 public Task StartAsync(){return Task.Run(()=>StartSegment());}
 void StartSegment(){current=new Segment{Video=Path.Combine(work,"segment-"+segments.Count.ToString("D3")+".mkv")};audio.Clear();try{if(settings.SystemAudio)audio.Add(new RecordingAudio(Path.Combine(work,"system-"+segments.Count+".wav"),true));if(settings.Microphone)audio.Add(new RecordingAudio(Path.Combine(work,"microphone-"+segments.Count+".wav"),false));foreach(var track in audio)current.Audio.Add(track.Path);string input=synthetic?"-re -f lavfi -i testsrc=size="+area.Width+"x"+area.Height+":rate=20":"-f gdigrab -framerate 20 -draw_mouse 1 -offset_x "+area.X+" -offset_y "+area.Y+" -video_size "+area.Width+"x"+area.Height+" -i desktop";string args="-hide_banner -loglevel error -nostats -progress pipe:2 -y "+input+" -an -vf \"pad=ceil(iw/2)*2:ceil(ih/2)*2\" -c:v libx264 -preset ultrafast -crf 23 -pix_fmt yuv420p "+RecordingRuntime.Q(current.Video);ready=new ManualResetEvent(false);errorLog.Clear();encoder=new Process{StartInfo=new ProcessStartInfo(RecordingRuntime.Tool("ffmpeg"),args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardError=true}};encoder.ErrorDataReceived+=(s,e)=>{if(e.Data==null)return;if(e.Data.StartsWith("frame=")){if(!firstFrameClock.IsRunning)firstFrameClock.Start();ready.Set();}else lock(errorLog){if(errorLog.Length<12000)errorLog.AppendLine(e.Data);}};encoder.Start();encoder.BeginErrorReadLine();if(!ready.WaitOne(12000)||encoder.HasExited)throw new Exception("录屏编码器未能启动："+errorLog.ToString());foreach(var track in audio){track.Start(firstFrameClock);current.Delays.Add(track.OffsetMs);}activeClock.Restart();Paused=false;segments.Add(current);}catch{foreach(var track in audio)try{track.Dispose();}catch{}audio.Clear();if(encoder!=null){try{if(!encoder.HasExited)encoder.Kill();}catch{}encoder.Dispose();encoder=null;}if(ready!=null){ready.Dispose();ready=null;}throw;}}
 void EndSegment(){if(current==null||encoder==null)return;activeClock.Stop();past+=activeClock.Elapsed;activeClock.Reset();Exception failure=null;foreach(var track in audio){try{track.Dispose();if(track.Fault!=null)failure=track.Fault;}catch(Exception e){failure=e;}}audio.Clear();try{if(!encoder.HasExited){encoder.StandardInput.WriteLine("q");encoder.StandardInput.Flush();if(!encoder.WaitForExit(15000)){encoder.Kill();throw new Exception("录屏进程停止超时，临时文件已保留");}}encoder.WaitForExit();if(encoder.ExitCode!=0)throw new Exception("录制中断，临时文件已保留："+errorLog.ToString());}finally{encoder.Dispose();encoder=null;ready.Dispose();ready=null;firstFrameClock.Reset();current=null;}if(failure!=null)throw new Exception("音频录制失败："+failure.Message);}
 public Task PauseAsync(){return Task.Run(()=>{EndSegment();Paused=true;});}
 public Task ResumeAsync(){return Task.Run(()=>StartSegment());}
 public Task StopAsync(){return Task.Run(()=>{EndSegment();if(segments.Count==0)throw new Exception("还没有录制内容");FinalizeVideo();Finalized=true;try{CleanupWork();}catch{}});}
 void FinalizeVideo(){foreach(var segment in segments){if(segment.Audio.Count==0){segment.Mixed=segment.Video;continue;}segment.Mixed=Path.ChangeExtension(segment.Video,".mp4");var args=new StringBuilder("-hide_banner -loglevel error -y -i "+RecordingRuntime.Q(segment.Video));for(int i=0;i<segment.Audio.Count;i++)args.Append(" -i "+RecordingRuntime.Q(segment.Audio[i]));var filter=new StringBuilder();for(int i=0;i<segment.Audio.Count;i++)filter.Append("["+(i+1)+":a]aresample=48000,aformat=channel_layouts=stereo,adelay="+segment.Delays[i]+":all=1,apad[a"+i+"];");for(int i=0;i<segment.Audio.Count;i++)filter.Append("[a"+i+"]");filter.Append(segment.Audio.Count>1?"amix=inputs="+segment.Audio.Count+":normalize=0,alimiter=limit=0.95[a]":"anull[a]");args.Append(" -filter_complex "+RecordingRuntime.Q(filter.ToString())+" -map 0:v:0 -map \"[a]\" -c:v copy -c:a aac -b:a 192k -shortest "+RecordingRuntime.Q(segment.Mixed));RecordingRuntime.Run("ffmpeg",args.ToString(),600000);}string list=Path.Combine(work,"segments.txt");File.WriteAllLines(list,segments.Select(s=>"file '"+s.Mixed.Replace("\\","/").Replace("'","'\\''")+"'"),new UTF8Encoding(false));string staged=Path.Combine(work,"finished.mp4");RecordingRuntime.Run("ffmpeg","-hide_banner -loglevel error -y -f concat -safe 0 -i "+RecordingRuntime.Q(list)+" -c copy -movflags +faststart "+RecordingRuntime.Q(staged),600000);if(new FileInfo(staged).Length<1000)throw new Exception("录屏输出为空，临时文件已保留");File.Move(staged,OutputPath);}
 public string VerifyOutput(){return RecordingRuntime.Run("ffprobe","-v error -show_entries format=duration:stream=codec_type,codec_name,width,height -of json "+RecordingRuntime.Q(OutputPath));}
 void CleanupWork(){string root=Path.GetFullPath(settings.Directory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string target=Path.GetFullPath(work);if(!target.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(target).StartsWith(".recording-",StringComparison.Ordinal))throw new Exception("临时目录校验失败");Directory.Delete(target,true);}
 public void Dispose(){if(disposed)return;disposed=true;try{EndSegment();}catch{}if(!Finalized&&segments.Count==0)try{CleanupWork();}catch{}}
}
